import{_ as o,a as e,b as n,c as t,d as a,e as A}from"./chunks/4.ADUvTKDR.js";import{_ as r,o as i,c as s,ag as l}from"./chunks/framework.lghGfHnE.js";const T=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"前端转AI Agent/01-AI Agent 开发要学什么？/README.md","filePath":"前端转AI Agent/01-AI Agent 开发要学什么？/README.md"}'),g={name:"前端转AI Agent/01-AI Agent 开发要学什么？/README.md"};function _(d,p,c,I,m,u){return i(),s("div",null,[...p[0]||(p[0]=[l('<p>我们每天都在用各种 AI Agent，比如用 Curosr 写代码，用 Manus 做各种自动化的事情。</p><p>那你有没有想过自己开发一个 AI Agent 产品呢？</p><p><img src="'+o+'" alt="图片"></p><p>有同学说，直接调大模型不就行了？</p><p>你可以想一下，大模型是不是有这些问题：</p><ul><li>你上周和它聊过的消息，它是不是记不住？</li><li>你让它帮你访问一个网页，做一些事情，它是不是只能告诉你思路让你自己做？</li><li>你想让它基于你公司内部的私密文档来做一些解答，它是不是不知道那是什么？</li><li>你问他刚发生的一个新闻，它是不是不知道？因为它训练的时候没这些数据</li></ul><p>这些问题的解决就需要分别给大模型加上 Memory 记忆能力、Tool 工具调用能力、RAG 文档查询能力等。</p><p>不管大模型怎么发展，它都没法解决这些：</p><ul><li>它的记忆总是有限的，需要开发者做 Memory 管理</li><li>它可以调的特定领域的工具，需要开发者开发好 Tool 交给它</li><li>它没办法对不知道的私密文档做解答，需要扩展 RAG 知识库查询能力</li></ul><p>这些就是我们要学的 AI 技术，也就是 AI Agent 的开发能力。</p><p>Agent 是什么？</p><p>其实就是给大模型扩展了 Tool 和 Memory。它本来就可以思考、规划，你给他用 Tool 扩展了能力，它就可以自动做事情了，用 Memory 管理了记忆，它就可以记住你想让它记住的东西，还可以用 RAG 查询内部知识库来获取知识。</p><p>这样一个知道内部知识、能思考规划、有记忆，能够帮你做事情的扩展后的大模型，就是一个 Agent。</p><p><img src="'+e+'" alt="图片"></p><p>你每天用的 Curosr 等 AI IDE，它是怎么读写文件、执行命令的？</p><p>比如改代码需要读写文件：</p><video src="'+n+'" controls></video><p>帮你运行代码需要执行命令：</p><video src="'+t+'" controls></video><p>如何实现的这些功能呢？很明显是扩展了 Tool。</p><p>帮你做各种事情的 Manus，是怎么唤起浏览器来自动访问一些网页，怎么执行命令，怎么帮你操作各种软件的？</p><p>看这个视频：</p><video src="'+a+'" controls></video><p>Manus 是怎么打开浏览器、访问网页，点击元素，帮你总结成文档，写入 md 文件的？</p><p>也是扩展了 Tool。</p><p>支付宝里的理财助手，可以帮你分析基金，推荐基金，它是怎么知道这些基金的数据的？</p><p>看这个视频：</p><video src="'+A+'" controls></video><p>支付宝蚂小财是怎么知道这些基金的数据的？是大模型本身就知道么？</p><p>肯定不是啊，是基于 RAG 来访问了内部的知识库。</p><p>类似的各种需要给大模型扩展能力的场景太多了。</p><p>光会和大模型聊天不行，你得能给它扩展各种能力，这样才能满足各种 AI 需求。</p><p>这就是我们学习 AI 技术的目标。</p><p>那 RAG、Memory、Tool、Agent 等用什么框架呢？</p><p>最常用的就是 LangChain，它对这些能力封装好了各种 api，可以直接用。</p><p>我在公司做 AI Agent 产品，就是基于 langchain 来开发。</p><p>它有 python 和 node 版，我们学的是 node 版。</p><p>其实语言是次要的，等你学会了 AI 技术，换语言来写也是很简单的事情，逻辑、概念都是一样的。</p><p>作为前端，肯定是 js、node 来上手学 AI 更顺滑啊！</p><p>所以这门课程是用 node + langchain + langgraph 来开发各种 Agent。</p><p>LangChain 是用来开发单个 Agent 的，每个 Agent 做一件事情。</p><p>但涉及到多个 Agent 协作，用 LangChain 自己维护多 Agent 的交互就比较麻烦了，这时候我们就要学习 LangGraph。</p><p>它是基于 LangChain 封装的，用于多 Agent 交互的框架。</p><p>学 AI 不要只学用 AI 做一些工具，最好是结合后端技术一起学，也就是 AI 全栈。</p><p>因为 AI 代码是在后端跑的，这时候你需要用 redis 存记忆、用 mysql 存知识等，这种就需要后端的知识了。</p><p>所以我们是后端 + AI 一起学，做 AI 全栈产品，node 后端框架用 Nest。</p><h2 id="总结" tabindex="-1"><strong>总结</strong> <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;**总结**&quot;">​</a></h2><p>给大模型扩展 Tool、Memory、RAG 等能力，让它可以去做一些具体的事情，这就是一个 Agent 了。</p><p>平时我们用的 cursor、manus 等工具都是 AI Agent。</p><p>我们会学习开发 Agent 用的 langchain 框架，开发 Multi Agent 用的 langgraph 框架，基于 node 版来学，学会了后面换语言也很简单，api、逻辑都一样。</p><p>我们会结合后端技术一起学，开发 AI 全栈产品。这样才能让 AI 技术落地到产品里，变成我们的竞争力，吃到这波 AI 时代的红利。</p><p><strong>测试搜索内容：AI智能助手 机器学习模型 深度学习框架 自然语言处理技术 语义理解算法</strong></p>',52)])])}const E=r(g,[["render",_]]);export{T as __pageData,E as default};
